genomic.annotation.detail.df.4 <- peakAnno.4@detailGenomicAnnotation
peaks.df.4 <- cbind(peaks.df.4, genomic.annotation.detail.df.4)

# Isolate Promoter (<=1kb) separately across genotypes

geno.1.promoter <- filter(peaks.df.1, annotation == "Promoter (<=1kb)") 

geno.2.promoter <- filter(peaks.df.2, annotation == "Promoter (<=1kb)")  

geno.3.promoter <- filter(peaks.df.3, annotation == "Promoter (<=1kb)") 

geno.4.promoter <- filter(peaks.df.4, annotation == "Promoter (<=1kb)")

# Filter promoters for unique gene names and adjusted pValue

pval.threshold <- -log10(0.00005)

geno.1.promoter <- filter(geno.1.promoter, pValue >= pval.threshold) 
genes.geno.1 <- unique(data.frame(gene = geno.1.promoter$geneId))
genes.geno.1$geno<- as.factor("1")
dim(genes.geno.1)


geno.2.promoter <- filter(geno.2.promoter, pValue >= pval.threshold)
genes.geno.2 <- unique(data.frame(gene = geno.2.promoter$geneId))
genes.geno.2$geno<- as.factor("2")
dim(genes.geno.2)

geno.3.promoter <- filter(geno.3.promoter, pValue >= pval.threshold) 
genes.geno.3 <- unique(data.frame(gene = geno.3.promoter$geneId))
genes.geno.3$geno<- as.factor("3")
dim(genes.geno.3)

geno.4.promoter <- filter(geno.4.promoter, pValue >= pval.threshold) 
genes.geno.4 <- unique(data.frame(gene = geno.4.promoter$geneId))
genes.geno.4$geno<- as.factor("4")
