  filter(gene %in% geneID_2_outta_4.df$gene)

# get rid of unneeded columns
merged.peak.data <- merged.peak.data %>%
  select(gene, signalValue, distanceToTSS, geno)

# Long to wide data
merged.peak.data$gene <- as.character(merged.peak.data$gene)
merged.peak.data$geno <- as.factor(merged.peak.data$geno)  # Ensure geno is treated as a factor


# Reshape to wide format
wide.merged.peak.data  <- as.data.frame(merged.peak.data %>%
  group_by(gene, geno) %>%
  summarise(
    mean_signalValue = mean(signalValue, na.rm = TRUE),
    mean_distanceToTSS = mean(distanceToTSS, na.rm = TRUE)
  ) %>%
  pivot_wider(
    id_cols = gene,
    names_from = geno,
    values_from = c(mean_signalValue, mean_distanceToTSS),
    names_prefix = "geno_"
  ))
head(wide.merged.peak.data)

dim(wide.merged.peak.data ) #4806

# Calculate overall averages excluding NA values
wide.merged.peak.data <- wide.merged.peak.data %>%
  mutate(
    mean_signalValue = rowMeans(select(., starts_with("mean_signalValue")), na.rm = TRUE),
    mean_distanceToTSS = rowMeans(select(., starts_with("mean_distanceToTSS")), na.rm = TRUE)
  )

