######## HRG with open and closed window -2Kb to 2Kb 

baseMean.HRG.4kb <- ggplot(padj.filtered.heat.response.results, aes(x = two.genos, y = log10(baseMean), fill = two.genos)) +
  # clouds
  introdataviz::geom_flat_violin(trim=FALSE,
                                 position = position_nudge(x = rain_height+.05)) +
  # rain
  geom_point(aes(color = two.genos), size = 2, alpha = 0.4,  show.legend = FALSE, 
             position = position_jitter(width = rain_height, height = 0)) +
  # boxplots
  geom_boxplot(width = rain_height, show.legend = FALSE, 
               outlier.shape = NA,
               position = position_nudge(x = -rain_height*2)) +
  coord_flip() +
  scale_fill_manual(values = c("#f7b267",
                               "#f27059")) +
  scale_color_manual(values = c("#f7b267",
                                "#f27059")) + 
  
  theme_pubr() +
  stat_compare_means(method = "wilcox.test",
                     comparisons = list(c("TRUE", "FALSE")),
                     label = "p.format",
                     step.increase = 0.05) +
  theme(legend.position = "none") +
  
  labs(x = "Open 4kb window", y = "Base Mean (log10)") +
  ggtitle("Heat response gene base mean\nwith open & closed 4kb window")
